
%% MATH 155 - Homework 3, Problem 3
% Gaussian Low-Pass and High-Pass Filtering
% Norah Lynch
%
% Apply frequency-domain Gaussian filters
% using the two-dimensional Fourier transform.
%
% This implementation does not require mat2gray
% or the Image Processing Toolbox for normalization.

clear; clc; close all;

%% Select input image
I = imread('HW3Q3_original_image.jpg');

%% Convert to grayscale if necessary
if size(I, 3) == 3
    % Manual RGB to grayscale conversion
    I = 0.2989 * double(I(:,:,1)) + ...
        0.5870 * double(I(:,:,2)) + ...
        0.1140 * double(I(:,:,3));
else
    I = double(I);
end

%% Normalize image to [0,1]
if max(I(:)) > 1
    f = I / 255;
else
    f = I;
end

%% Get image dimensions
[M, N] = size(f);

%% Compute 2D Fourier transform
F = fft2(f);

%% Shift zero-frequency component to center
F_shifted = fftshift(F);

%% Create centered frequency coordinate grid
[u, v] = meshgrid( ...
    (0:N-1) - floor(N/2), ...
    (0:M-1) - floor(M/2));

%% Compute squared distance from frequency origin
D2 = u.^2 + v.^2;

%% Gaussian cutoff frequency
D0 = 15;

%% ============================================
% PART A: GAUSSIAN LOW-PASS FILTER
% =============================================

% Gaussian low-pass transfer function
H_low = exp(-D2 / (2 * D0^2));

% Apply filter in frequency domain
G_low = H_low .* F_shifted;

% Inverse Fourier transform
g_low = real(ifft2(ifftshift(G_low)));

% Clip pixel intensities to [0,1]
g_low_display = max(0, min(1, g_low));

%% Display low-pass results
figure('Name', 'Gaussian Low-Pass Filtering', ... %[output:570e7dab]
       'Position', [100 100 1200 400]); %[output:570e7dab]

subplot(1,3,1); %[output:570e7dab]
imagesc(f); %[output:570e7dab]
axis image off; %[output:570e7dab]
colormap gray; %[output:570e7dab]
title('Original Image'); %[output:570e7dab]

subplot(1,3,2); %[output:570e7dab]
imagesc(H_low); %[output:570e7dab]
axis image off; %[output:570e7dab]
title('Gaussian Low-Pass Filter'); %[output:570e7dab]

subplot(1,3,3); %[output:570e7dab]
imagesc(g_low_display); %[output:570e7dab]
axis image off; %[output:570e7dab]
title('Low-Pass Filtered Image'); %[output:570e7dab]

%% Save low-pass outputs
imwrite(g_low_display, 'HW3_P3_lowpass.png');

exportgraphics(gcf, ... %[output:group:0f0aecb0] %[output:570e7dab]
    'HW3_P3_lowpass_comparison.png'); %[output:group:0f0aecb0] %[output:570e7dab]

%% ============================================
% PART B: GAUSSIAN HIGH-PASS FILTER
% =============================================

% Gaussian high-pass transfer function
H_high = 1 - H_low;

% Apply filter in frequency domain
G_high = H_high .* F_shifted;

% Inverse Fourier transform
g_high = real(ifft2(ifftshift(G_high)));

%% Normalize high-pass image for visualization
% Replaces mat2gray(g_high)

highDisplay = g_high - min(g_high(:));

if max(highDisplay(:)) > 0
    highDisplay = highDisplay / max(highDisplay(:));
end

%% Display high-pass results
figure('Name', 'Gaussian High-Pass Filtering', ... %[output:48536fc0]
       'Position', [100 100 1200 400]); %[output:48536fc0]

subplot(1,3,1); %[output:48536fc0]
imagesc(f); %[output:48536fc0]
axis image off; %[output:48536fc0]
colormap gray; %[output:48536fc0]
title('Original Image'); %[output:48536fc0]

subplot(1,3,2); %[output:48536fc0]
imagesc(H_high); %[output:48536fc0]
axis image off; %[output:48536fc0]
title('Gaussian High-Pass Filter'); %[output:48536fc0]

subplot(1,3,3); %[output:48536fc0]
imagesc(highDisplay); %[output:48536fc0]
axis image off; %[output:48536fc0]
title('High-Pass Filtered Image'); %[output:48536fc0]

%% Save high-pass outputs
imwrite(highDisplay, 'HW3_P3_highpass.png');

exportgraphics(gcf, ... %[output:group:18271e17] %[output:48536fc0]
    'HW3_P3_highpass_comparison.png'); %[output:group:18271e17] %[output:48536fc0]

%% ============================================
% SAVE FILTER VISUALIZATIONS
% =============================================

%% Normalize low-pass filter
lowFilterDisplay = H_low - min(H_low(:));

if max(lowFilterDisplay(:)) > 0
    lowFilterDisplay = ...
        lowFilterDisplay / max(lowFilterDisplay(:));
end

imwrite(lowFilterDisplay, ...
    'HW3_P3_lowpass_filter.png');

%% Normalize high-pass filter
highFilterDisplay = H_high - min(H_high(:));

if max(highFilterDisplay(:)) > 0
    highFilterDisplay = ...
        highFilterDisplay / max(highFilterDisplay(:));
end

imwrite(highFilterDisplay, ...
    'HW3_P3_highpass_filter.png');

%% ============================================
% DISPLAY COMPUTATIONAL INFORMATION
% =============================================

fprintf('\n');
fprintf('MATH 155 - Homework 3, Problem 3\n'); %[output:6a852947]
fprintf('Gaussian Frequency-Domain Filtering\n'); %[output:2e0ce141]
fprintf('-----------------------------------\n'); %[output:0acf9a5d]

fprintf('Image dimensions: %d x %d\n', M, N); %[output:91d12d8a]
fprintf('Gaussian cutoff frequency D0 = %.2f\n', D0); %[output:0aa2175d]

fprintf('\nLow-pass filtering completed.\n'); %[output:12ee9193]
fprintf('High-pass filtering completed.\n'); %[output:59274be7]

fprintf('\nAll output images saved successfully.\n'); %[output:463f7b65]

%% End of script


